function h({registerIndicator:u,sourceValues:m,nulls:p}){u({id:"oa-ema",name:"Exponential Moving Average (EMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"ema",type:"line",title:"EMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,n){const d=Math.max(1,Math.floor(Number(n.period)||10)),f=m(o,n.source??"close"),r=2/(d+1),y=1-r,a=new Array(o.length).fill(NaN);let e=0,l=1,c=!0;for(let t=0;t<o.length;t++){const i=f[t];if(Number.isFinite(i))if(e=r*(i-e)+e,c){l*=y;const s=1-l;a[t]=s!==0?e/s:e,c=l>1e-10}else a[t]=e}return{ema:p(a)}}})}export{h as default};
